import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import '../api/api_client.dart'  import '../widgets/loading_widget.dart'  import '../widgets/empty_state.dart'    class DealsScreen extends ConsumerStatefulWidget {    const DealsScreen({super.key})      @override    ConsumerState<DealsScreen> createState() => _DealsScreenState()  }    class _DealsScreenState extends ConsumerState<DealsScreen> {    List<dynamic> _deals = []    List<dynamic> _stages = []    bool _isLoading = true    int _selectedStageIndex = 0      @override    void initState() {      super.initState()      _loadData()    }      Future<void> _loadData() async {      try {        final [deals, stages] = await Future.wait([          ApiClient().getDeals(),          ApiClient().getPipelineStages(),        ])        if (mounted) setState(() {          _deals = deals          _stages = stages          _isLoading = false        })      } catch (e) {        if (mounted) setState(() => _isLoading = false)      }    }      Future<void> _moveDeal(int dealId, int stageId) async {      try {        await ApiClient().moveDeal(dealId, stageId)        _loadData()        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            const SnackBar(content: Text('Сделка перемещена')),          )        }      } catch (e) {        if (mounted) {          ScaffoldMessenger.of(context).showSnackBar(            SnackBar(content: Text('Ошибка: $e')),          )        }      }    }      Future<void> _showAddDealDialog() async {      final titleController = TextEditingController()      final amountController = TextEditingController()      int? selectedStageId        await showModalBottomSheet(        context: context,        isScrollControlled: true,        shape: const RoundedRectangleBorder(          borderRadius: BorderRadius.vertical(top: Radius.circular(20)),        ),        builder: (context) => StatefulBuilder(          builder: (context, setModalState) => Padding(            padding: EdgeInsets.only(              bottom: MediaQuery.of(context).viewInsets.bottom,              left: 20,              right: 20,              top: 20,            ),            child: Column(              mainAxisSize: MainAxisSize.min,              crossAxisAlignment: CrossAxisAlignment.stretch,              children: [                Row(                  mainAxisAlignment: MainAxisAlignment.spaceBetween,                  children: [                    const Text('Новая сделка', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),                    IconButton(                      icon: const Icon(Icons.close),                      onPressed: () => Navigator.pop(context),                    ),                  ],                ),                const SizedBox(height: 16),                TextField(                  controller: titleController,                  decoration: InputDecoration(                    labelText: 'Название сделки *',                    prefixIcon: const Icon(Icons.title),                    border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                  ),                ),                const SizedBox(height: 12),                TextField(                  controller: amountController,                  keyboardType: TextInputType.number,                  decoration: InputDecoration(                    labelText: 'Сумма (₽)',                    prefixIcon: const Icon(Icons.currency_ruble),                    border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                  ),                ),                const SizedBox(height: 12),                if (_stages.isNotEmpty)                  DropdownButtonFormField<int>(                    value: selectedStageId,                    decoration: InputDecoration(                      labelText: 'Этап воронки',                      border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                    ),                    items: _stages.map<DropdownMenuItem<int>>((stage) {                      return DropdownMenuItem<int>(                        value: stage['id'],                        child: Text(stage['name']),                      )                    }).toList(),                    onChanged: (value) => setModalState(() => selectedStageId = value),                  ),                const SizedBox(height: 20),                ElevatedButton(                  onPressed: () async {                    if (titleController.text.isEmpty) return                    try {                      await ApiClient().createDeal({                        'title': titleController.text,                        'amount': amountController.text.isNotEmpty ? double.parse(amountController.text) : null,                        'stage_id': selectedStageId,                        'priority': 'medium',                      })                      if (mounted) {                        Navigator.pop(context)                        _loadData()                        ScaffoldMessenger.of(context).showSnackBar(                          const SnackBar(content: Text('Сделка создана')),                        )                      }                    } catch (e) {                      ScaffoldMessenger.of(context).showSnackBar(                        SnackBar(content: Text('Ошибка: $e')),                      )                    }                  },                  style: ElevatedButton.styleFrom(                    padding: const EdgeInsets.symmetric(vertical: 16),                    shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),                  ),                  child: const Text('Создать', style: TextStyle(fontSize: 16)),                ),                const SizedBox(height: 20),              ],            ),          ),        ),      )    }      Color _getStageColor(dynamic stage) {      final colorStr = stage['color']?.toString() ?? '#64748b'      return Color(int.parse(colorStr.replaceFirst('#', '0xFF')))    }      String _getPriorityLabel(String? priority) {      final labels = {'low': 'Низкий', 'medium': 'Средний', 'high': 'Высокий', 'urgent': 'Срочный'}      return labels[priority] ?? 'Средний'    }      Color _getPriorityColor(String? priority) {      final colors = {        'low': Colors.grey,        'medium': Colors.blue,        'high': Colors.orange,        'urgent': Colors.red,      }      return colors[priority] ?? Colors.blue    }      @override    Widget build(BuildContext context) {      return Scaffold(        appBar: AppBar(          title: const Text('Сделки'),          actions: [            IconButton(              icon: const Icon(Icons.add),              onPressed: _showAddDealDialog,            ),          ],        ),        body: _isLoading            ? const LoadingWidget()            : Column(                children: [                  // Stage tabs                  if (_stages.isNotEmpty)                    Container(                      height: 50,                      padding: const EdgeInsets.symmetric(horizontal: 8),                      child: ListView.builder(                        scrollDirection: Axis.horizontal,                        itemCount: _stages.length,                        itemBuilder: (context, index) {                          final stage = _stages[index]                          final isSelected = index == _selectedStageIndex                          return Padding(                            padding: const EdgeInsets.symmetric(horizontal: 4),                            child: ChoiceChip(                              label: Text(                                '${stage['name']} (${_deals.where((d) => d['stage_id'] == stage['id']).length})',                                style: TextStyle(                                  color: isSelected ? Colors.white : _getStageColor(stage),                                  fontSize: 12,                                ),                              ),                              selected: isSelected,                              selectedColor: _getStageColor(stage),                              backgroundColor: _getStageColor(stage).withOpacity(0.1),                              onSelected: (_) => setState(() => _selectedStageIndex = index),                            ),                          )                        },                      ),                    ),                    // Deals list                  Expanded(                    child: _deals.isEmpty                        ? const EmptyState(                            icon: Icons.handshake_outlined,                            title: 'Нет сделок',                            subtitle: 'Создайте первую сделку',                          )                        : RefreshIndicator(                            onRefresh: _loadData,                            child: ListView.builder(                              padding: const EdgeInsets.all(16),                              itemCount: _deals.length,                              itemBuilder: (context, index) {                                final deal = _deals[index]                                final stage = _stages.firstWhere(                                  (s) => s['id'] == deal['stage_id'],                                  orElse: () => {'name': 'Без этапа', 'color': '#64748b'},                                )                                  return Card(                                  margin: const EdgeInsets.only(bottom: 12),                                  child: Column(                                    crossAxisAlignment: CrossAxisAlignment.start,                                    children: [                                      ListTile(                                        title: Text(                                          deal['title'] ?? 'Без названия',                                          style: const TextStyle(fontWeight: FontWeight.w600),                                        ),                                        subtitle: Text(                                          '${deal['amount']?.toString() ?? '0'} ₽',                                          style: TextStyle(                                            color: Theme.of(context).colorScheme.primary,                                            fontWeight: FontWeight.bold,                                          ),                                        ),                                        trailing: Container(                                          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),                                          decoration: BoxDecoration(                                            color: _getPriorityColor(deal['priority']).withOpacity(0.1),                                            borderRadius: BorderRadius.circular(8),                                          ),                                          child: Text(                                            _getPriorityLabel(deal['priority']),                                            style: TextStyle(                                              fontSize: 10,                                              color: _getPriorityColor(deal['priority']),                                            ),                                          ),                                        ),                                      ),                                      // Stage indicator                                      Padding(                                        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),                                        child: Row(                                          children: [                                            Container(                                              width: 8,                                              height: 8,                                              decoration: BoxDecoration(                                                color: _getStageColor(stage),                                                shape: BoxShape.circle,                                              ),                                            ),                                            const SizedBox(width: 8),                                            Text(                                              stage['name'],                                              style: TextStyle(fontSize: 12, color: Colors.grey[600]),                                            ),                                            const Spacer(),                                            if (deal['probability'] != null)                                              Text(                                                '${deal['probability']}%',                                                style: TextStyle(fontSize: 12, color: Colors.grey[600]),                                              ),                                          ],                                        ),                                      ),                                      // Move buttons                                      if (_stages.length > 1)                                        Padding(                                          padding: const EdgeInsets.fromLTRB(16, 0, 16, 12),                                          child: Wrap(                                            spacing: 8,                                            children: _stages                                            .where((s) => s['id'] != deal['stage_id'])                                            .map((s) => ActionChip(                                              label: Text(s['name'], style: const TextStyle(fontSize: 11)),                                              backgroundColor: _getStageColor(s).withOpacity(0.1),                                              side: BorderSide(color: _getStageColor(s)),                                              onPressed: () => _moveDeal(deal['id'], s['id']),                                            )).toList(),                                          ),                                        ),                                    ],                                  ),                                )                              },                            ),                          ),                  ),                ],              ),      )    }  }